import{_ as l,a0 as p,w as r,s as u,ao as i,I as a,x as e,a1 as s,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"使用 Linux 終端瀏覽你的計算機 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Linux 終端瀏覽你的計算機 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Linux 終端瀏覽你的計算機 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Linux 終端瀏覽你的計算機 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210803 Use the Linux terminal to navigate throughout your computer","title":"使用 Linux 終端瀏覽你的計算機","tag":"202108","desc":""},"relativePath":"202108/20210803 Use the Linux terminal to navigate throughout your computer.md","filePath":"[post].md"}'),d={name:"202108/20210803 Use the Linux terminal to navigate throughout your computer.md"};function m(x,t,T,g,f,b){const n=p("Link");return r(),u("div",null,[t[24]||(t[24]=i('<h1 id="使用-linux-終端瀏覽你的計算機" tabindex="-1">使用 Linux 終端瀏覽你的計算機 <a class="header-anchor" href="#使用-linux-終端瀏覽你的計算機" aria-label="Permalink to “使用 Linux 終端瀏覽你的計算機”">​</a></h1><blockquote><p>學習在 Linux 終端中從一個目錄切換到另一個目錄。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202108/12/113605d3hp448xm8m18wzw.jpg" alt=""></p><p>要在圖形界面中瀏覽你的計算機上的文件夾，你可能習慣於打開一個窗口來“進入”你的計算機，然後雙擊一個文件夾，再雙擊一個子文件夾，如此反覆。你也可以使用箭頭按鈕或按鍵來回溯。</p><p>而要在終端中瀏覽你的計算機，你可以利用 <code>cd</code> 命令。你可以使用 <code>cd ..</code> 回到 <em>上一級</em> 目錄，或者使用 <code>cd ./另一個/文件夾的/路徑</code> 來跳過許多文件夾進入一個特定的位置。</p>',5)),a("p",null,[t[1]||(t[1]=e("你在互聯網上已經使用的 URL 的概念，實際上直接來自 ",-1)),s(n,{href:"https://opensource.com/article/19/7/what-posix-richard-stallman-explains"},{default:o(()=>[...t[0]||(t[0]=[e("POSIX",-1)])]),_:1}),t[2]||(t[2]=e("。當你瀏覽某個網站的一個特定頁面時，比如 ",-1)),t[3]||(t[3]=a("code",null,"http://www.example.com/tutorials/lesson2.html",-1)),t[4]||(t[4]=e("，你實際上做的是進入 ",-1)),t[5]||(t[5]=a("code",null,"/var/www/imaginarysite/tutorials/",-1)),t[6]||(t[6]=e(" 目錄，並打開一個叫 ",-1)),t[7]||(t[7]=a("code",null,"classic2.html",-1)),t[8]||(t[8]=e(" 的文件。當然，你是在 Web 瀏覽器中打開它的，瀏覽器會將所有那些看起來奇怪的 HTML 代碼解釋成漂亮的文本和圖片。但這兩者的思路是完全一樣的。",-1))]),t[25]||(t[25]=i(`<p>如果你把你的計算機看成是互聯網（或者把互聯網看成是計算機會更合適），那麼你就能理解如何在你的文件夾和文件中遨遊了。如果從你的用户文件夾（你的家目錄，或簡記為 <code>~</code>）開始，那麼你想切換到的文件夾都是相對於這個文件夾而言的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd ~/Documents</span></span>
<span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/tux/Documents</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ cd ..</span></span>
<span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/tux</span></span></code></pre></div><p>這需要一些練習，但一段時間後，它會變得比你打開和關閉窗口、點擊返回按鈕和文件夾圖標快得多。</p><h3 id="用-tab-鍵自動補全" tabindex="-1">用 Tab 鍵自動補全 <a class="header-anchor" href="#用-tab-鍵自動補全" aria-label="Permalink to “用 Tab 鍵自動補全”">​</a></h3><p>鍵盤上的 <code>Tab</code> 鍵可以自動補全你開始輸入的文件夾和文件的名字。如果你要 <code>cd</code> 到 <code>~/Documents</code> 文件夾，那麼你只需要輸入 <code>cd ~/Doc</code>，然後按 <code>Tab</code> 鍵即可。你的 Shell 會自動補全 <code>uments</code>。這不僅僅是一個令人愉快的便利工具，它也是一種防止錯誤的方法。如果你按下 <code>Tab</code> 鍵而沒有任何東西自動補全，那麼可能你 <em>認為</em> 存在於某個位置的文件或文件件實際上並不存在。即使有經驗的 Linux 用户也會試圖切換到一個當前目錄下不存在的文件夾，所以你可以經常使用 <code>pwd</code> 和 <code>ls</code> 命令來確認你確實在你認為你在的目錄、以及你的當前目錄確實包含了你認為它包含的文件。</p><hr>`,6)),a("p",null,[t[10]||(t[10]=e("via: ",-1)),s(n,{href:"https://opensource.com/article/21/8/navigate-linux-directories"},{default:o(()=>[...t[9]||(t[9]=[e("https://opensource.com/article/21/8/navigate-linux-directories",-1)])]),_:1})]),a("p",null,[t[15]||(t[15]=e("作者：",-1)),s(n,{href:"https://opensource.com/users/seth"},{default:o(()=>[...t[11]||(t[11]=[e("Seth Kenlon",-1)])]),_:1}),t[16]||(t[16]=e(" 選題：",-1)),s(n,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[12]||(t[12]=[e("lujun9972",-1)])]),_:1}),t[17]||(t[17]=e(" 譯者：",-1)),s(n,{href:"https://github.com/piaoshi"},{default:o(()=>[...t[13]||(t[13]=[e("piaoshi",-1)])]),_:1}),t[18]||(t[18]=e(" 校對：",-1)),s(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[14]||(t[14]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[21]||(t[21]=e("本文由 ",-1)),s(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[19]||(t[19]=[e("LCTT",-1)])]),_:1}),t[22]||(t[22]=e(" 原創編譯，",-1)),s(n,{href:"https://linux.cn/"},{default:o(()=>[...t[20]||(t[20]=[e("Linux中國",-1)])]),_:1}),t[23]||(t[23]=e(" 榮譽推出",-1))])])}const k=l(d,[["render",m]]);export{C as __pageData,k as default};
